// Shared boot-service composition. Image/overlay lifecycle and IRQ/DSP epochs
// stay with the board coordinator. Unbound services are explicit handoffs.
class ControllerStartupServicesHolder final {
 using G=ControllerStartupGraph;using S=ControllerStartupServicesRuntime;using C=StartupChild;
 enum class Owner:uint8_t{None,Metadata,Arp,Banner,Program,Tables,Buttons,Simple,Volume,MidiInit,Keyboard,Adc,Flash,Display};
public:
 enum class Route:uint8_t{Ready,External,Invalid};enum class Block:uint8_t{None,NotBound,Inactive,NeedsInterrupt,External,Invalid};struct Result{unsigned clocks=0;bool returned=false;Block blocked=Block::None;};
 bool bindBootResources(ControllerDeviceState&d,const uint8_t*image,size_t size){if(bootBound_||bound_||active()||!simple_.bindBootResources(d,image,size)||!volume_.bindBootResources(d,image,size)||!keyboard_.bindBootResources(d,image,size)||!buttons_.bindBootResources(d,image,size)||!banner_.bindBootResources(d,image,size)||!update_.bindBootResources(d,image,size))return false;bootBound_=&d;return true;}
 bool bindAllMirrored(ControllerDeviceState&d,const uint8_t*image,size_t size){if(bootBound_!=&d||bound_||active()||!simple_.bindMirroredFirmware(d,image,size)||!volume_.bindMirroredFirmware(d,image,size)||!keyboard_.bindMirroredFirmware(d,image,size)||!buttons_.bindMirroredFirmware(d,image,size)||!adc_.bindVerifiedFirmware(d,image,size)||!programRefresh_.bindVerifiedFirmware(d,image,size)||!programInit_.bindVerifiedFirmware(d,image,size)||!programVoices_.bindVerifiedFirmware(d,image,size)||!program_.bindVerifiedFirmware(d,image,size)||!metadata_.bindVerifiedFirmware(d,image,size)||!arp_.bindVerifiedFirmware(d,image,size)||!tables_.bindVerifiedFirmware(d,image,size)||!banner_.bindMirroredFirmware(d,image,size)||!update_.bindMirroredFirmware(d,image,size)||!flash_.bindVerifiedFirmware(d,image,size)||!display_.bindVerifiedFirmware(d,image,size))return false;bound_=&d;return true;}
 bool boundTo(const ControllerDeviceState&d)const{return bound_==&d;}bool active()const{return owner_!=Owner::None;}void reset(){owner_=Owner::None;pending_=C::None;graph_=nullptr;program_.reset();programRefresh_.reset();programInit_.reset();programVoices_.reset();metadata_.reset();arp_.reset();banner_.reset();update_.reset();tables_.reset();buttons_.reset();simple_.reset();volume_.reset();keyboard_.reset();adc_.reset();flash_.reset();display_.reset();}
 Route route(G&graph,ControllerDeviceState&d,ControllerInterruptRuntime&irq,ControllerDspTransferRuntime&dsp,ControllerMidiServices&midi,ControllerVoiceServices&voice,ControllerNumericDisplayRuntime&numeric){(void)voice;if(bootBound_!=&d||!graph.boundTo(d))return Route::Invalid;auto q=graph.request();if(q.service!=G::Service::Startup)return Route::External;if(active()){if(graph_!=&graph||q.startup!=pending_)return Route::Invalid;if(owner_==Owner::Buttons&&buttons_.request()==ControllerStartupButtonsRuntime::Request::UpdateMode&&!update_.active()){if((!irq.boundTo(d)&&irq.mask()!=ControllerInterruptRuntime::Mask::Disabled)||!update_.start())return Route::Invalid;}if(owner_==Owner::Program&&!program_.routeServices(d,programServices(dsp,graph)))return Route::External;return owner_==Owner::Display&&display_.request().service!=ControllerStartupDisplayRuntime::Service::None?Route::External:Route::Ready;}
  if(q.startup==C::BootProbe){if(!buttons_.start())return Route::Invalid;owner_=Owner::Buttons;pending_=q.startup;graph_=&graph;return Route::Ready;}
  switch(q.startup){case C::Metadata:case C::ArpInitialize:case C::StartupBanner:case C::LoadProgram:case C::DelayTables:case C::SerialEnable:case C::MidiInitialize:case C::KeyboardInitialize:case C::AdcStart:case C::Scheduler1:case C::Scheduler2:case C::Scheduler3:case C::Scheduler4:case C::Scheduler5:case C::ClockInitialize:case C::ReadAdc:case C::ReadTick:case C::ApplyAdc:case C::BackupGlobals:case C::LoadGlobals:case C::ClearUi:case C::UpdateDisplay:break;default:return Route::External;}
  if(bound_!=&d||!irq.boundTo(d)||!dsp.boundTo(d)||!numeric.boundTo(d)||!graph.lcd().boundTo(d)||!graph.panel().boundTo(d))return Route::Invalid;bool ok=false;Owner owner=Owner::None;switch(q.startup){case C::Metadata:ok=metadata_.start();owner=Owner::Metadata;break;case C::ArpInitialize:ok=arp_.start();owner=Owner::Arp;break;case C::StartupBanner:ok=banner_.start();owner=Owner::Banner;break;case C::LoadProgram:ok=program_.start();owner=Owner::Program;break;case C::DelayTables:ok=tables_.start();owner=Owner::Tables;break;case C::SerialEnable:case C::MidiInitialize:if(!midi.boundTo(d)||midi.active()||midi.initActive())return Route::Invalid;ok=midi.startInit(q.startup==C::SerialEnable?ControllerMidiInitRuntime::Kind::SerialEnable:ControllerMidiInitRuntime::Kind::Initialize);owner=Owner::MidiInit;break;case C::KeyboardInitialize:ok=keyboard_.start(ControllerStartupKeyboardRuntime::Kind::Initialize);owner=Owner::Keyboard;break;case C::AdcStart:ok=adc_.start(ControllerStartupAdcRuntime::Kind::Initialize);owner=Owner::Adc;break;case C::Scheduler1:case C::Scheduler2:case C::Scheduler3:case C::Scheduler4:case C::Scheduler5:ok=simple_.start(S::Kind::ClearScheduler,uint8_t(unsigned(q.startup)-unsigned(C::Scheduler1)));owner=Owner::Simple;break;case C::ClockInitialize:ok=simple_.start(S::Kind::ClockInitialize);owner=Owner::Simple;break;case C::ReadAdc:ok=simple_.start(S::Kind::ReadAdc,uint8_t(q.value));owner=Owner::Simple;break;case C::ReadTick:ok=simple_.start(S::Kind::ReadTick);owner=Owner::Simple;break;case C::ApplyAdc:if(dsp.active())return Route::Invalid;ok=volume_.start(uint8_t(q.value));owner=Owner::Volume;break;case C::BackupGlobals:if(graph.lcd().active())return Route::Invalid;ok=flash_.start(ControllerFlashStateRuntime::Kind::BackupGlobals,0,q.resource);owner=Owner::Flash;break;case C::LoadGlobals:ok=flash_.start(ControllerFlashStateRuntime::Kind::LoadGlobals);owner=Owner::Flash;break;case C::ClearUi:case C::UpdateDisplay:if(graph.lcd().active()||graph.panel().active()||numeric.active())return Route::Invalid;ok=display_.start(q.startup==C::ClearUi?StartupDisplayTask::Kind::ClearSelection:StartupDisplayTask::Kind::Refresh);owner=Owner::Display;break;default:break;}if(!ok)return Route::Invalid;owner_=owner;pending_=q.startup;graph_=&graph;return Route::Ready;
 }
 ControllerStartupBannerRuntime&banner(){return banner_;}
 bool completeUpdateMode(G&graph,ControllerDeviceState&d,ControllerInterruptRuntime&irq){if(owner_!=Owner::Buttons||graph_!=&graph||update_.active()||!buttons_.completeUpdateMode())return false;return finish(graph,d,irq);}
 ControllerStartupButtonsRuntime::Request buttonRequest()const{return update_.active()?ControllerStartupButtonsRuntime::Request::None:buttons_.request();}
 ControllerStartupDisplayRuntime::Request displayRequest()const{return display_.request();}
 bool completeDisplayService(G&graph,ControllerDeviceState&d,ControllerInterruptRuntime&irq,ControllerStartupDisplayRuntime::Service service){if(owner_!=Owner::Display||graph_!=&graph||!display_.completeService(service))return false;return display_.active()||finish(graph,d,irq);}
 unsigned nextClocks(const ControllerDeviceState&d,const ControllerInterruptRuntime&irq,const ControllerDspTransferRuntime&dsp,const ControllerMidiServices&midi,const ControllerVoiceServices&voice,const ControllerNumericDisplayRuntime&numeric)const{(void)voice;if(bootBound_!=&d||(bound_!=&d&&owner_!=Owner::Buttons)||!active()||!graph_)return 0;switch(owner_){case Owner::Metadata:return metadata_.nextClocks(d,irq,flash_,graph_->lcd());case Owner::Arp:return arp_.nextClocks(d,irq);case Owner::Banner:return banner_.nextClocks(d,irq,numeric,graph_->lcd());case Owner::Program:return program_.nextClocks(d,irq,ControllerProgramStateRuntime::ConstServices{dsp,graph_->panel(),programRefresh_,programInit_,programVoices_});case Owner::Tables:return tables_.nextClocks(d,irq);case Owner::Buttons:return update_.active()?update_.nextClocks(d,irq,graph_->lcd(),numeric):buttons_.nextClocks(d,irq,graph_->lcd());case Owner::Simple:return simple_.nextClocks(d,irq);case Owner::Volume:return volume_.nextClocks(d,irq,dsp);case Owner::MidiInit:return midi.nextInit(d,irq);case Owner::Keyboard:return keyboard_.nextClocks(d,irq);case Owner::Adc:return adc_.nextClocks(d,irq);case Owner::Flash:return flash_.nextClocks(d,irq,graph_->lcd());case Owner::Display:return display_.nextClocks(d,irq,graph_->panel(),numeric,graph_->lcd());default:return 0;}}
 Result advanceBefore(G&graph,ControllerDeviceState&d,ControllerInterruptRuntime&irq,ControllerDspTransferRuntime&dsp,ControllerMidiServices&midi,ControllerVoiceServices&voice,ControllerNumericDisplayRuntime&numeric,unsigned budget){(void)voice;if(bootBound_!=&d||(bound_!=&d&&owner_!=Owner::Buttons)||graph_!=&graph)return {0,false,Block::NotBound};if(!active())return {0,false,Block::Inactive};auto q=graph.request();if(q.service!=G::Service::Startup||q.startup!=pending_)return {0,false,Block::Invalid};unsigned clocks=0;bool returned=false;Block block=Block::None;auto accept=[&](auto r){clocks=r.clocks;returned=r.returned;using B=decltype(r.blocked);block=r.blocked==B::None?Block::None:r.blocked==B::NeedsInterrupt?Block::NeedsInterrupt:Block::External;};switch(owner_){case Owner::Metadata:accept(metadata_.advanceBefore(d,irq,flash_,graph.lcd(),budget));break;case Owner::Arp:accept(arp_.advanceBefore(d,irq,budget));break;case Owner::Banner:accept(banner_.advanceBefore(d,irq,numeric,graph.lcd(),budget));break;case Owner::Program:accept(program_.advanceBefore(d,irq,programServices(dsp,graph),budget));break;case Owner::Tables:accept(tables_.advanceBefore(d,irq,budget));break;case Owner::Buttons:if(update_.active()){auto r=update_.advanceBefore(d,irq,graph.lcd(),numeric,budget);accept(r);if(r.returned&&!buttons_.completeUpdateMode())return {clocks,false,Block::Invalid};}else accept(buttons_.advanceBefore(d,irq,graph.lcd(),budget));break;case Owner::Simple:accept(simple_.advanceBefore(d,irq,budget));break;case Owner::Volume:accept(volume_.advanceBefore(d,irq,dsp,budget));break;case Owner::MidiInit:accept(midi.advanceInit(d,irq,budget));break;case Owner::Keyboard:accept(keyboard_.advanceBefore(d,irq,budget));break;case Owner::Adc:accept(adc_.advanceBefore(d,irq,budget));break;case Owner::Flash:accept(flash_.advanceBefore(d,irq,graph.lcd(),budget));break;case Owner::Display:accept(display_.advanceBefore(d,irq,graph.panel(),numeric,graph.lcd(),budget));break;default:return {0,false,Block::Inactive};}if(returned&&!finish(graph,d,irq))return {clocks,false,Block::Invalid};return {clocks,returned,block};}
private:
 ControllerProgramStateRuntime::Services programServices(ControllerDspTransferRuntime&dsp,G&graph){return {dsp,graph.panel(),programRefresh_,programInit_,programVoices_};}
 bool finish(G&graph,ControllerDeviceState&d,ControllerInterruptRuntime&irq){auto value=owner_==Owner::Simple?simple_.value():0;auto pending=pending_;owner_=Owner::None;pending_=C::None;graph_=nullptr;return graph.completeService(G::Service::Startup,d,irq,value,pending);}
 ControllerDeviceState*bootBound_=nullptr,*bound_=nullptr;G*graph_=nullptr;Owner owner_=Owner::None;C pending_=C::None;S simple_;ControllerStartupVolumeRuntime volume_;ControllerStartupKeyboardRuntime keyboard_;ControllerStartupAdcRuntime adc_;ControllerFlashStateRuntime flash_;ControllerStartupDisplayRuntime display_;ControllerStartupButtonsRuntime buttons_;ControllerStartupTablesRuntime tables_;ControllerStartupBannerRuntime banner_;ControllerFirmwareReceiveWorkflow update_;ControllerMetadataRuntime metadata_;ControllerStartupArpRuntime arp_;ControllerProgramStateRuntime program_;ControllerPanelRefreshRuntime programRefresh_;ControllerProgramVoiceInitRuntime programInit_;ControllerProgramVoicesRuntime programVoices_;
};
